<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {ElMessageBox} from 'element-plus';
import {isResolved} from '../utils/health';
import {api} from '../api/client';
const props=defineProps({mappings:{type:Array,default:()=>[]}});
const view=ref({events:[],incidents:[]}),error=ref(''),busy=ref(false),enabled=ref(false),webhook=ref(''),token=ref(''),maintenance=ref('keep');
let controller,disposed=false,initialized=false,loadVersion=0,baselineEnabled=false;
const saving=ref(false),configRevision=ref('');
function acceptView(data){const pristine=!initialized||(enabled.value===baselineEnabled&&!webhook.value&&!token.value&&maintenance.value==='keep');view.value=data;if(pristine){enabled.value=!!data.enabled;baselineEnabled=!!data.enabled;configRevision.value=data.revision||'';initialized=true}}
async function load(){if(busy.value||saving.value)return;busy.value=true;const version=++loadVersion;controller=new AbortController();try{const data=await api.operations(controller.signal);if(!disposed&&version===loadVersion){acceptView(data);error.value=data.revision&&configRevision.value&&data.revision!==configRevision.value?'通知配置已更新，请重新加载后编辑':''}}catch(e){if(!disposed&&version===loadVersion&&e.name!=='AbortError')error.value=e.message}finally{if(!disposed&&version===loadVersion)busy.value=false}}
async function save(){if(saving.value||!initialized)return;saving.value=true;loadVersion++;controller?.abort();busy.value=false;try{let until=view.value.maintenance_until;if(maintenance.value==='off')until=new Date(0).toISOString();if(maintenance.value==='hour')until=new Date(Date.now()+3600000).toISOString();if(maintenance.value==='day')until=new Date(Date.now()+86400000).toISOString();const data=await api.saveNotifications({enabled:enabled.value,webhook:webhook.value,token:token.value,revision:configRevision.value,maintenance_until:until||new Date(0).toISOString()});if(!disposed){webhook.value='';token.value='';maintenance.value='keep';initialized=false;acceptView(data);error.value=''}}catch(e){if(!disposed)error.value=e.message}finally{if(!disposed)saving.value=false}}
async function reloadConfig(){if(saving.value)return;try{await ElMessageBox.confirm('重新加载会放弃未保存的通知配置。','重新加载配置',{confirmButtonText:'重新加载',cancelButtonText:'返回编辑'});if(disposed)return;loadVersion++;controller?.abort();busy.value=false;webhook.value='';token.value='';maintenance.value='keep';initialized=false;await load()}catch(e){if(e!=='cancel'&&e!=='close'&&!disposed)error.value=e.message}}
const recent=computed(()=>[...(view.value.events||[])].reverse().slice(0,30));
const incidents=computed(()=>[...(view.value.incidents||[])].sort((a,b)=>Number(isResolved(a))-Number(isResolved(b))||new Date(b.started)-new Date(a.started)).slice(0,20));
const labels={'duplicate-session':'同账号重复拨号 · 请检查地址冲突','shared-upstream':'多节点同时异常 · 公共链路待核验','local-unstable':'本地转发异常','local-recovering':'恢复中','local-circuit-open':'自动恢复冷却','upstream':'节点转发异常','dns':'DNS 异常','unknown':'检测数据过期或尚未采集'};
const eventLabels={'incident-ended':'监测结束','incident-changed':'故障分类变化','session-limit':'PPP 会话上限','rule-repair':'规则修复','process-recovery':'进程恢复','incident-open':'故障开始','incident-recovered':'故障结束','ppp-up':'拨号上线','ppp-down':'拨号下线','operation':'管理操作','session-disconnect':'断开会话','connection-close':'关闭连接'};
function time(t){return t&&!t.startsWith('0001')?new Date(t).toLocaleString():'—'}
const connectionMap=ref(''),connectionRows=ref([]),connectionError=ref(''),connectionBusy=ref(false),connectionShown=ref(false),truncated=ref(false);
let connectionController,connectionVersion=0;
function closeConnections(){connectionVersion++;connectionController?.abort();connectionShown.value=false;connectionBusy.value=false;connectionRows.value=[]}
async function connections(id){closeConnections();connectionMap.value=id;connectionShown.value=true;connectionBusy.value=true;connectionError.value='';const version=connectionVersion;connectionController=new AbortController();try{const d=await api.connections(id,connectionController.signal);if(version===connectionVersion&&!disposed){connectionRows.value=d.rows||[];truncated.value=d.truncated}}catch(e){if(version===connectionVersion&&!disposed&&e.name!=='AbortError')connectionError.value=e.message}finally{if(version===connectionVersion&&!disposed)connectionBusy.value=false}}
const closingConnection=ref('');
async function endConnection(row){if(closingConnection.value)return;const mapping=connectionMap.value,version=connectionVersion;try{await ElMessageBox.confirm('关闭此连接？应用可能重新建立连接。','连接管理',{type:'warning'});if(disposed||version!==connectionVersion||!connectionShown.value)return;closingConnection.value=row.id;await api.closeConnection(mapping,row.id);if(!disposed&&version===connectionVersion)await connections(mapping)}catch(e){if(!disposed&&version===connectionVersion&&e!=='cancel'&&e!=='close')connectionError.value=e.message}finally{closingConnection.value=''}}

onMounted(load);const timer=setInterval(load,15000);onBeforeUnmount(()=>{disposed=true;controller?.abort();closeConnections();clearInterval(timer)});
</script>
<template>
<el-card shadow="never" class="section-gap operations-panel"><template #header>故障事件与操作记录</template>
<el-alert v-if="error||view.warning" :title="error||view.warning" type="warning" :closable="false"/>
<el-button :loading="busy" @click="load">刷新事件</el-button>
<p v-if="!incidents.length" class="muted">暂无故障事件</p>
<article v-for="row in incidents" :key="row.key+row.started" class="operation-row"><strong>{{labels[row.state]||row.state}} · {{isResolved(row)?'已结束':'处理中'}}</strong><p>{{row.scope==='node'?'节点关联':row.scope==='server-suspected'?'公共故障关联':'映射'}} · {{row.affected.join('、')}}</p><p>{{time(row.started)}} → {{time(row.resolved)}}</p></article>
<el-collapse><el-collapse-item title="最近操作与拨号事件" name="events"><article v-for="row in recent" :key="row.id" class="operation-row"><strong>{{eventLabels[row.kind]||row.kind}} · {{row.resource}}</strong><p>{{time(row.at)}} · {{row.detail}}</p></article><p v-if="!recent.length" class="muted">暂无记录</p></el-collapse-item>
<el-collapse-item title="故障通知" name="notifications"><el-form label-position="top" :disabled="saving||!initialized"><el-form-item label="通知开关"><el-switch v-model="enabled"/></el-form-item><el-form-item label="HTTPS Webhook"><el-input v-model="webhook" placeholder="留空保留原地址" autocomplete="off"/></el-form-item><el-form-item label="Bearer Token"><el-input v-model="token" type="password" show-password placeholder="更换地址时请重新填写令牌" autocomplete="new-password"/></el-form-item><el-form-item label="维护静默"><el-select v-model="maintenance"><el-option value="keep" label="保留当前设置"/><el-option value="off" label="结束静默"/><el-option value="hour" label="静默 1 小时"/><el-option value="day" label="静默 24 小时"/></el-select></el-form-item><p class="muted">已配置：{{view.configured?'是':'否'}} · {{view.delivery||'暂无发送记录'}} · 静默至 {{time(view.maintenance_until)}}</p><el-button :loading="saving" :disabled="!initialized" @click="save">保存通知设置</el-button><el-button :disabled="saving" @click="reloadConfig">重新加载配置</el-button></el-form></el-collapse-item></el-collapse>
</el-card>
<el-card shadow="never" class="section-gap"><template #header>映射连接</template><div class="connection-controls"><el-button v-for="m in mappings.filter(m=>m.status==='running')" :key="m.id" @click="connections(m.id)">{{m.tun_name}} · 查看连接</el-button></div><p class="muted">按需读取，最多显示 500 条；目标信息不写入历史。</p></el-card>
<el-dialog v-model="connectionShown" title="当前连接" width="min(760px, calc(100vw - 24px))" append-to-body class="connections-dialog" @close="closeConnections"><el-alert v-if="connectionError" :title="connectionError" type="warning" :closable="false"/><p v-if="connectionBusy">读取中…</p><p v-else-if="!connectionRows.length&&!connectionError">暂无连接</p><p v-if="truncated">连接较多，仅展示前 500 条。</p><article v-for="row in connectionRows" :key="row.id" class="operation-row"><strong>{{row.metadata.host||row.metadata.destinationIP}}:{{row.metadata.destinationPort}}</strong><p>{{row.metadata.network}} · 建立于 {{time(row.start)}}</p><p>上传 {{row.upload}} B · 下载 {{row.download}} B</p><el-button size="small" :disabled="!!closingConnection" :loading="closingConnection===row.id" @click="endConnection(row)">关闭连接</el-button></article></el-dialog>
</template>
<style scoped>.operation-row{overflow-wrap:anywhere;padding:12px 0;border-bottom:1px solid var(--el-border-color-lighter)}.operation-row p{margin:7px 0;font-size:13px}.connection-controls{display:flex;flex-wrap:wrap;gap:8px}.connection-controls .el-button{margin:0}.operations-panel .el-form{max-width:620px}</style>
